{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Metolazone, which shares the 2,6-dimethylphenyl and 5-chloro-4-sulfamoylbenzamide core with the query, has approximately 100% absolute oral bioavailability in humans, directly supporting a high F prediction for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Valdecoxib, a sulfonamide-containing drug, has an absolute oral bioavailability of 83% in humans, demonstrating that primary sulfonamide/aromatic amide drugs are generally well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Meloxicam, an acidic enol carboxamide with a sulfonamide-like group, shows 91% absolute oral bioavailability in healthy fasting volunteers, supporting high absorption for acidic heteroaromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "PF-05241328, a sulfonamide-containing compound, has an absolute oral bioavailability of 38% in humans, still well above the 20% threshold and supporting that this chemotype is not inherently low-F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfamoylbenzamide diuretic closely related to metolazone, which is ~100% bioavailable; multiple high-transfer sulfonamide/amide analogues show absolute oral bioavailability of 38–91%, all above the 20% threshold. Therefore the query is predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule; prediction relies on close analogues.",
    "The celecoxib record reports low bioavailability (20–40%) due to poor solubility, but this range is at/above the 20% threshold and is not directly transferable to the query's scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

